cd /workspace && python3 - << 'EOF'
import os, resource, errno, ctypes
def t(name, fn):
    pid=os.fork()
    if pid==0:
        try:
            fn(); os._exit(0)
        except BaseException as e:
            print("  child fail:", name, type(e).__name__, e, flush=True); os._exit(1)
    _,st=os.waitpid(pid,0)
    print(name, "->", os.waitstatus_to_exitcode(st))
def setsid(): os.setsid()
def lim():
    for kind,pair in ((resource.RLIMIT_AS,(2*1024**3,2*1024**3)),(resource.RLIMIT_CPU,(180,181)),
                      (resource.RLIMIT_NOFILE,(256,256)),(resource.RLIMIT_NPROC,(64,64)),
                      (resource.RLIMIT_FSIZE,(64*1024**2,64*1024**2)),(resource.RLIMIT_CORE,(0,0))):
        resource.setrlimit(kind,pair)
t("setsid", setsid)
t("limits", lim)
t("setsid+limits", lambda: (os.setsid(), lim()))
EOF
